CREATE TABLE IF NOT EXISTS safety_training_modules (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  code VARCHAR(50) NOT NULL,
  title VARCHAR(255) NOT NULL,
  description TEXT,
  transcript MEDIUMTEXT,
  audio_url VARCHAR(500) DEFAULT NULL,
  duration_seconds INT UNSIGNED DEFAULT NULL,
  sort_order INT UNSIGNED NOT NULL DEFAULT 1,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_training_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS safety_training_progress (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id INT NULL,
  driver_id INT NULL,
  identity_key VARCHAR(40) NOT NULL,
  module_id INT UNSIGNED NOT NULL,
  position_seconds INT UNSIGNED NOT NULL DEFAULT 0,
  completed TINYINT(1) NOT NULL DEFAULT 0,
  updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_training_progress_identity (identity_key, module_id),
  KEY idx_training_progress_user (user_id),
  KEY idx_training_progress_driver (driver_id),
  KEY idx_training_progress_module (module_id),
  CONSTRAINT fk_training_module FOREIGN KEY (module_id) REFERENCES safety_training_modules (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_1', 'Training 1 — Road Safety Policy', 'Audio + transcript for Air Liquide Road Safety Policy (Hindi).', 'सड़क सुरक्षा नीति\nएयर लिक्विड इंडिया अपनी गतिविधियों में शामिल सभी लोगों के स्वास्थ्य और सुरक्षा के लिए, सड़क दुर्घटनाओं की रोकथाम करने पर केंद्रित है। यह स्पष्ट उद्देश्य एयर लिक्विड प्रबंधन की एक मजबूत प्रतिबद्धता और थकान सुरक्षा प्रबंधन, ड्राइविंग व्यवहार प्रबंधन, वाहन विनिर्देश और सड़क सुरक्षा कार्यक्रम के माध्यम से और अधिक के नियमों का पालन करने की अपेक्षा से निर्देशित है।\n\nइस प्रतिबद्धता की पूर्ति हेतु एयर लिक्विड इंडिया:-\n● आवश्यक संवैधानिक एवं प्रासंगिक मानकों का अनुपालन करेगी तथा सुनिश्चित करेगी कि हमारे सभी अनु-बन्धक इस नीति से अवगत हैं और सभी लागू मानकों का पालन कर रहे हैं।\n● सेवाओं में सुधार के लिए परिवहन अनुबन्धकों का नियमित निरीक्षण एवं जाँच करेगी (उदाहरण: प्रतिबन्धित समय, गति सीमा का पालन, थकान सुरक्षा प्रबंधन इत्यादि)।\n● सड़क सर्वेक्षण के द्वारा जोखिम की पहचान व उनके समाधान और रात के विश्राम के लिए सुरक्षित स्थानों की पहचान करेगी।\n● वाहन चालकों के लिए नियमित प्रशिक्षण एवं योग्यता आकलन का संचालन करेगी।\n● आकलन द्वारा सुनिश्चित करेगी कि वाहन सम्बंधित प्रयोजन के लिए उपयुक्त है और सम्बंधित एयर लिक्विड या स्थानीय मानकों में जो भी अधिक सख्त हो, का अनुपालन किया जायेगा।\n● वाहन का निर्माता विनिर्देशों एवं स्थानीय नियमों के अनुसार रखरखाव करेगी।\n● उत्सर्जन को कम करने के लिए पर्यावरण संवेदनशीलता को ध्यान में रखकर वाहन परिचालन करेगी तथा अपने सभी उत्पाद वाहन चालकों को रक्षात्मक ड्राइविंग एवं रोल-ओवर की रोकथाम की तकनीकों पर प्रशिक्षित करेगी।\n● अपने सभी उत्पाद वाहनों को वैकल्पिक ट्रैकिंग सिस्टम (VTS) तथा कैमरों से सुसज्जित करेगी; जिससे ड्राइवर के ड्राइविंग व्यवहार और थकान प्रबंधन की निगरानी और विश्लेषण करेगी।\n● सड़क यात्रा की चुनौतियों एवं जोखिमों को कम करने के लिए अन्य विकल्पों पर विचार करेगी।\n\nवाहन परिचालन के समय निम्नलिखित नियमों का पालन अनिवार्य है:-\n● सीट बेल्ट का प्रयोग सभी के लिए अनिवार्य है। किसी भी वाहन में यात्रियों की संख्या वाहन में उपलब्ध कार्यात्मक सीट बेल्टों की संख्या से अधिक न हो।\n● वाहन चालक के पास उपयुक्त लाइसेंस, प्रशिक्षण तथा वाहन संचालन के लिए कार्यात्मक दक्षता एवं चिकित्सीय रूप से फिट होना अनिवार्य है।\n● थकान को रोकने एवं सुरक्षित वाहन परिचालन हेतु चालक को पर्याप्त विश्राम एवं अवकाश प्रदान करना और प्रत्येक 2 घंटे की ड्राइविंग के बाद 15 मिनट का विराम अनुशंसित है।\n● किसी भी प्रकार के नशे (शराब, ड्रग्स एवं नशीली दवाओं का प्रयोग जिससे संचालन क्षमता पर असर पड़े) के प्रभाव में वाहन संचालन निषिद्ध है।\n● वाहन के भीतर या एयर लिक्विड संयंत्र परिसर या ग्राहक परिसर में धूम्रपान निषिद्ध है।\n● कंपनी संचालित वाहनों के केबिन एवं निजी वाहनों में गैस सिलेंडरों का परिवहन वर्जित है।\n● वाहन चलाते समय कॉल, पाठ संदेश या किसी अन्य उपयोग के लिए ड्राइवर मोबाइल फोन का उपयोग नहीं करेगा।\n● वाहन चालक को सड़क पर चलने वाले अन्य वाहनों एवं पद-यात्रियों के हितों का ध्यान रखना अनिवार्य है।\n● सभी एयर लिक्विड एवं अनुबन्धित कर्मचारियों को दुपहिया वाहन चलाते हुए हेलमेट पहनना अनिवार्य है (चालक एवं सवारी)।\n● दुपहिया वाहन पर दो से अधिक व्यक्तियों का यात्रा करना वर्जित है।\n● उत्पाद वाहनों का रात्रि में परिचालन (रात्रि 11:30 बजे से प्रातः 04:30 बजे तक) पूर्णतया प्रतिबन्धित है, यथासंभव अन्य वाहनों के परिचालन को भी रोकें।\n● उत्पाद वाहनों के लिए गति सीमा राजमार्गों पर 50 किमी/घंटा और अन्य मार्गों पर 40 किमी/घंटा सीमित है। स्कूलों के निकट गति सीमा 15 किमी/घंटा एवं गावों तथा सार्वजनिक स्थलों के निकट 20 किमी/घंटा सीमित है। यदि सड़क गति सीमा उपरोक्त गति सीमा से कम है तो सड़क गति सीमा का पालन करें।\n● कार और दुपहिया वाहन उपयोगकर्ता सड़क गति सीमा का पालन करें।\n● आपातकालीन परिस्थिति में वाहन रोकते समय उपयुक्त एहतियाती उपायों का पालन किया जाना चाहिए (जैसे- ट्रैफिक कोन, रिफ्लेक्टर ट्रैंगल)।\n● सभी घटनाओं और दुर्घटनाओं को तुरंत एयर लिक्विड इंडिया के रोड सेफ्टी एवं स्वास्थ्य, सुरक्षा एवं पर्यावरण विभाग (HSE) को फोन द्वारा या ई-मेल पर सूचित करें: Safety.ALINDIA@airliquide.com तथा इंटेलेक्स पर भी रिपोर्ट करें।\n\nयह सड़क सुरक्षा नीति सभी कर्मचारियों (नियमित एवं उप-अनुबन्धित) और अनुबन्धकों जो एयर लिक्विड इंडिया में या के लिए कार्यरत हैं, पर लागू है। सड़क सुरक्षा नीति को सभी स्थानों पर लागू करने का उत्तरदायित्व सम्बंधित प्रबंधकों का है।', '/DriverDocs/audio/training/training1.mp3', 0, 1, 1)
ON DUPLICATE KEY UPDATE
  title = VALUES(title),
  description = VALUES(description),
  transcript = VALUES(transcript),
  audio_url = VALUES(audio_url),
  sort_order = VALUES(sort_order),
  is_active = VALUES(is_active);

INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_2', 'Training 2 — Breakdown & Rescue Responsibilities', 'Hindi breakdown protocol for drivers and rescue teams with contacts.', 'ड्राइवर की ज़िम्मेदारी
• सुपरवाइज़र और S&T को सूचित करें।
• ट्रक की हेजार्ड लाइट्स चालू करें। अपना चमकदार जैकेट पहनें।
• हैंड ब्रेक लगाएँ, सड़क पर ट्रैफिक न होने पर ही बाहर निकलें।
• अपनी आँखें हर समय सड़क पर रखें, कभी भी विचलित न हों और ट्रैफिक कोन को उचित निर्णय अनुसार रखें।
• ट्रक में चढ़ने या उतरने से पहले सुपरवाइज़र को सूचित करें; बचाव दल पहचान हेतु पूछ सकता है।
• आवश्यक हो तो बचाव अभियानों में सहायता करें।
• गंभीर घटना में आपातकालीन योजना अनुसार कार्य करें।

Image: https://sstranswaysindia.com/DriverDocs/training/images/breakdown_module2.png

बचाव दल की ज़िम्मेदारी
• ब्रेकडाउन स्पॉट पर पहुँचें।
• ड्राइवर और सहायक को पानी/जलपान दें।
• बैरिकेड्स और आवश्यक कोन लगाएँ।
• बचाव अभियान शुरू करें।

