INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_3', 'Training 3 — Truck Rollover Prevention', 'Hindi transcript on preventing truck rollovers.', 'ट्रक रोलओवर(ट्रक के पलटने) रोकथाम
ट्रक के पलटने (रोलओवर) की दुर्घटनाएँ बहुत खतरनाक होती हैं। इन्हें सही जानकारी और सावधानी से रोका जा सकता है।
 
ट्रक के पलटने के मुख्य कारण
1. मोड़ पर तेज गति से गाड़ी ले जाना
2. अचानक स्टीयरिंग मोड़ देना
3. थकान या नींद के साथ ड्राइव करना
4. कच्चे या टूटे हुए सड़क किनारे चलाना
5. ढलान (टिल्टेड) सड़क पर गाड़ी पार्क करना
6. ट्रक में तकनीकी खराबियाँ (टायर फटना, सस्पेंशन खराब होना आदि)
 
1. मोड़ पर तेज गति
• मोड़ पर ट्रक तेजी से ले जाने पर शरीर पर केन्द्रापसारक बल बढ़ जाता है।
• यह बल बढ़ने पर ट्रक संतुलन खोकर पलट सकता है।
• मोड़ पर 15 किमी/घंटा से अधिक गति न रखें।
• गति का अंदाज़ अनुमान से नहीं लगाना—स्पीडोमीटर देखें।
 
2. अचानक मोड़ लेना
• तेजी से स्टीयरिंग मोड़ने पर ट्रक का गुरुत्वाकर्षण संतुलन बिगड़ जाता है।
• इसका परिणाम—नियंत्रण खोना और ट्रक का पलटना।
कैसे बचें:
• सड़क पर आगे तक ध्यान से देखें।
• बचाव का रास्ता खुला रखें (escape space)।
 
3. थकान और नींद
• नींद या थकान आना ट्रक पलटने का बड़ा कारण है।
• थके होने पर कभी ड्राइव न करें।
• पर्याप्त आराम करें और काम/आराम के घंटे की नीति का पालन करें।
 
4. कच्ची सड़क किनारे चलाना
• भारी वाहनों का वजन सड़क के कच्चे हिस्से नहीं झेल पाते।
• ट्रक का एक पहिया सड़क से बाहर जाने पर वह झुक सकता है और पलट सकता है।
• सड़क किनारे ट्रक पार्क न करें।
 
5. ढलान वाली सड़क पर पार्किंग
• ढलान पर पार्क करने से ट्रक का वजन एक तरफ झुक जाता है।
• इससे ट्रक के पलटने का खतरा बढ़ जाता है।
 
6. तकनीकी खराबियाँ
1. टायर फटना
   o आगे का टायर फटने पर स्टीयरिंग पर नियंत्रण खत्म हो सकता है।
2. सस्पेंशन या स्टीयरिंग जॉइंट खराब होना
   o इससे वाहन असंतुलित होकर पलट सकता है।
रखरखाव महत्वपूर्ण है:
अच्छा रखरखाव रोलओवर रोकने में बड़ी भूमिका निभाता है।
 
रक्षात्मक ड्राइविंग के 5 मुख्य नियम
1. बहुत आगे देखें।
2. पूरी स्थिति समझें (बड़ी तस्वीर देखें)।
3. आँखें हमेशा सक्रिय रखें (चारों ओर देखें)।
4. खुद के लिए बचाव का रास्ता रखें।
5. दूसरों को यह सुनिश्चित करें कि वे आपको देख सकें।', NULL, 0, 3, 1)
ON DUPLICATE KEY UPDATE
  title = VALUES(title),
  description = VALUES(description),
  transcript = VALUES(transcript),
  audio_url = VALUES(audio_url),
  sort_order = VALUES(sort_order),
  is_active = VALUES(is_active);

INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_4', 'Training 4 — Intoxication & Smoking Risk', 'Hindi transcript on risks of intoxication and smoking inside vehicles.', 'वाहन के अंदर नशा और धूम्रपान का खतरा
Risk of Intoxication & Smoking inside the Vehicle
 
1. नशे में वाहन चलाने का खतरा
• ड्राइविंग करते समय शराब, ड्रग्स या किसी भी नशीले पदार्थ का इस्तेमाल बिल्कुल मना है।
• नशे में वाहन चलाना अपने और दूसरों दोनों के लिए बहुत खतरनाक है।
• नशा सड़क दुर्घटनाओं की संभावना को कई गुना बढ़ा देता है।
• यदि रक्त में अल्कोहल की मात्रा (BAC) 0.05 ग्राम/डेसिलीटर से ज्यादा हो जाए तो दुर्घटना होने का जोखिम बहुत बढ़ जाता है।
 
2. वाहन के अंदर धूम्रपान का खतरा
• वाहन के अंदर धूम्रपान करना सख्त मना है।
• ग्राहक के परिसर (Customer premises) और प्लांट के अंदर भी धूम्रपान पूरी तरह प्रतिबंधित है।
• वाहन के अंदर धूम्रपान करने से आग लगने का खतरा होता है।
 
3. निष्कर्ष
• सुरक्षित ड्राइविंग के लिए नशा और धूम्रपान दोनों से दूर रहें।
• नियमों का पालन करें और अपनी तथा दूसरों की सुरक्षा सुनिश्चित करें।', NULL, 0, 4, 1)
ON DUPLICATE KEY UPDATE
  title = VALUES(title),
