INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_5', 'Training 5 — Road Rage & Speed Risk', 'Hindi transcript on road rage and speeding risks.', '🚗 Road Rage और Speed Risk
⭐ 1. Road Rage क्या है?
Road Rage का मतलब है — सड़क पर वाहन चलाते समय गुस्सा, चिढ़ या आक्रामक व्यवहार दिखाना।
इसमें क्या–क्या आता है?
• किसी वाहन को पास न मिलने पर गुस्सा करना
• तेज हॉर्न बजाना
• दूसरे चालक को गाली देना, डराना या पीछा करना
• जानबूझकर ओवरटेक करने की कोशिश
• वाहन को अचानक ब्रेक लगाकर रोक देना
• हाथ के इशारे या खतरनाक हरकतें करना
ऐसा गुस्सा क्यों आता है?
• ट्रैफिक जाम
• किसी का गलत तरीके से ओवरटेक करना
• समय की जल्दी
• थकान या तनाव
• गर्मी का मौसम
• धैर्य की कमी
 
⭐ 2. Road Rage के खतरे
• दुर्घटना होने की संभावना कई गुना बढ़ जाती है
• खुद की और दूसरों की जान जोखिम में पड़ती है
• वाहन को नुकसान हो सकता है
• झगड़ा, मारपीट या कानूनन कार्रवाई हो सकती है
• मनोवैज्ञानिक तनाव बढ़ता है
 
⭐ 3. Road Rage को कैसे रोकें?
✔ शांत रहें
• गहरी सांस लें
• चाय–पानी पीकर थोड़ी देर आराम करें
• जल्दी में न चलें—समय से पहले निकलें
✔ दूसरे चालकों की गलतियाँ नजरअंदाज करें
• हर किसी का ड्राइविंग लेवल एक जैसा नहीं होता
• गलती से टकराव नहीं करना चाहिए
✔ गाड़ी में तेज म्यूजिक, फोन का उपयोग न करें
• इससे चिड़चिड़ापन बढ़ता है
✔ खतरा लगे तो दूरी बनाए रखें
• सामने वाला गुस्से में है तो पास न जाएँ
• बहस न करें
• जरूरत हो तो पुलिस को सूचित करें
 
⚡ Speed Risk (अत्यधिक गति का खतरा)
⭐ 1. तेज गति क्यों खतरनाक है?
• वाहन को नियंत्रित करना मुश्किल हो जाता है
• ब्रेक लगाने की दूरी बढ़ जाती है
• सड़क की स्थिति (गड्ढा, मोड़, स्पीड ब्रेकर) पर तुरंत प्रतिक्रिया नहीं दे पाते
• टक्कर की तीव्रता कई गुना बढ़ जाती है
 
⭐ 2. तेज गति से होने वाले नुकसान
• गंभीर सड़क दुर्घटना
• मौत या स्थायी चोट
• वाहन का भारी नुकसान
• दूसरों की जान भी जोखिम में
 
⭐ 3. गति नियंत्रण कैसे करें?
✔ Speed limit का पालन करें
हर सड़क, हाईवे और शहर की अपनी स्पीड सीमा होती है। उसे न भूलें।
✔ मौसम और सड़क को देखें
• बारिश, कोहरा, रात—इन स्थितियों में गति कम रखें
✔ मोबाइल, ईयरफोन या ध्यान भटकाने वाली चीजों से दूरी
तेज गति + ध्यान भटकना = सबसे बड़ा खतरा
✔ वाहन की दूरी बनाए रखें
सामने वाली गाड़ी से 3 सेकंड का अंतर रखें
 
🚦 Road Rage + Speed Risk = सबसे खतरनाक संयोजन
अगर कोई व्यक्ति गुस्से में आकर तेज गति से गाड़ी चलाता है, तो दुर्घटना की संभावना अत्यधिक बढ़ जाती है।
इसलिए शांत मन + सुरक्षित गति—यही सुरक्षित ड्राइविंग की चाबी है।', NULL, 0, 5, 1)
ON DUPLICATE KEY UPDATE
