INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_6', 'Training 6 — Mobile Use & Road Accidents', 'Hindi transcript on road accident risk from mobile phone use.', '📱 सड़क दुर्घटनाएँ और मोबाइल फोन का उपयोग
 
⭐ 1. मोबाइल फ़ोन के कारण सड़क दुर्घटनाएँ
दुनिया भर में मोबाइल फोन का उपयोग सड़क दुर्घटनाओं का एक बड़ा कारण बन गया है। भारत में हर साल लगभग 2.31 लाख लोग सड़क दुर्घटनाओं में अपनी जान गंवाते हैं।
इनमें से लगभग आधा हिस्सा कमजोर सड़क उपयोगकर्ताओं का होता है —
• मोटरसाइकिल चालक
• पैदल यात्री
• साइकिल चालक
इन दुर्घटनाओं का एक बड़ा कारण है—ड्राइविंग करते समय मोबाइल फोन का उपयोग।
 
⭐ 2. भारत में सड़क दुर्घटनाओं की स्थिति
भारत में सड़क दुर्घटनाएँ बहुत तेजी से बढ़ रही हैं। सबसे ज्यादा हादसे उन्हीं जगहों पर होते हैं जहाँ लोग—
• तेज गाड़ी चलाते हैं
• मोबाइल देखते हुए ड्राइव करते हैं
• ट्रैफिक नियमों का पालन नहीं करते
• हेलमेट, सीट बेल्ट आदि का उपयोग नहीं करते
मोबाइल फोन का उपयोग दुर्घटनाओं का प्रमुख कारण है क्योंकि इससे ड्राइवर का ध्यान सड़क से हट जाता है.
 
⭐ 3. सड़क सुरक्षा के प्रति हमारी प्रतिबद्धता
हर व्यक्ति की ज़िम्मेदारी है कि वह सड़क सुरक्षा नियमों का पालन करे।
कंपनी और ड्राइवर दोनों की प्रतिबद्धता होनी चाहिए:
✔ सड़क सुरक्षा के सभी नियमों का पालन करें
Signal, speed limit, zebra crossing, आदि का पालन करना जरूरी है।
✔ सभी कानूनी नियमों और मानकों का सम्मान करें
• हेलमेट
• सीट बेल्ट
• गाड़ी की नियमित जाँच
• सही दस्तावेज़
✔ वाहन को हमेशा सुरक्षित स्थिति में रखें
• ब्रेक
• इंडिकेटर
• हेडलाइट
• टायर
इनकी नियमित जाँच से दुर्घटनाएँ काफी कम होती हैं।
 
⭐ 4. ड्राइविंग करते समय मोबाइल फोन और मैसेज का उपयोग
📵 यह क्यों खतरनाक है?
ड्राइविंग करते समय मोबाइल फोन का उपयोग करने से:
• ध्यान सड़क से हट जाता है
• प्रतिक्रिया (reaction) धीमी हो जाती है
• अचानक ब्रेक लगाने या मुड़ने में देर होती है
• आगे का ट्रैफिक नजर नहीं आता
• हादसे की संभावना कई गुना बढ़ जाती है
✔ नियम 
❌ वाहन चलाते समय चालक को:
• फोन नहीं उठाना है
• फोन कॉल नहीं करना है
• मैसेज नहीं पढ़ना है
• मैसेज नहीं भेजना है
• हेडफोन/ईयरफोन नहीं लगाना है
• हैंड-फ्री डिवाइस भी नहीं इस्तेमाल करना है
मोबाइल फोन का उपयोग करते हुए ड्राइव करना कानूनी अपराध है।
 
⭐ 5. मोबाइल का उपयोग क्यों न करें?
• 1–2 सेकंड फोन देखने में भी गाड़ी 10–20 मीटर आगे बढ़ जाती है
• छोटे से ध्यान भटकाव से भी बड़ी दुर्घटना हो सकती है
• खुद की और दूसरों की जान को खतरा होता है
• वाहन का भारी नुकसान होता है
• कानूनी जुर्माना और लाइसेंस तक रद्द हो सकता है
 
⭐ 6. सुरक्षित ड्राइविंग के सुझाव
✔ ड्राइविंग शुरू करने से पहले फोन साइलेंट पर रखें
✔ जरूरत हो तो गाड़ी रोककर ही फोन का उपयोग करें
✔ गाड़ी में "Do Not Disturb" मोड ऑन करें
✔ लंबी यात्रा में रेस्ट ब्रेक लें
✔ ऑफिस/घर वालों को बताएँ कि ड्राइविंग के दौरान फोन न करें
 
⭐ निष्कर्ष
मोबाइल फोन का उपयोग सड़क दुर्घटनाओं का एक बहुत बड़ा कारण है।
इसलिए सुरक्षित ड्राइविंग के लिए—
👉 “पहले सड़क – फिर मोबाइल”- यही सबसे सही नियम है।', NULL, 0, 6, 1)
ON DUPLICATE KEY UPDATE
  title = VALUES(title),
  description = VALUES(description),
  transcript = VALUES(transcript),
  audio_url = VALUES(audio_url),
  sort_order = VALUES(sort_order),
  is_active = VALUES(is_active);

INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_8', 'Training 8 — First Aid Kit', 'Hindi transcript on first aid kit essentials and maintenance.', '🩹 प्राथमिक चिकित्सा किट (First Aid Kit)
प्राथमिक चिकित्सा किट किसी भी वाहन, विशेषकर Air Liquide के उत्पाद परिवहन वाहनों का बहुत महत्वपूर्ण हिस्सा है।

यह किट दुर्घटना, चोट या अचानक बीमारी के समय तुरंत मदद करने के लिए होती है।
अगर किट पूरी और सही हालत में हो, तो बड़ी दुर्घटनाओं में भी बहुत उपयोगी साबित होती है।
 
⭐ 1. प्राथमिक चिकित्सा किट क्यों जरूरी है?
• यात्रा के दौरान किसी को चोट लग सकती है।
• वाहन में छोटे-मोटे हादसे हो सकते हैं।
• फिसलन, सर्दी, धुंध या खराब मौसम में दुर्घटना की संभावना ज्यादा होती है।
• अस्पताल दूर हो सकता है, इसलिए तुरंत इलाज जरूरी होता है।
इसलिए फर्स्ट-एड किट हमेशा पूरी और अपडेटेड होनी चाहिए।
 
⭐ 2. फर्स्ट-एड किट कैसी होनी चाहिए?
• इसमें सभी जरूरी दवाएँ और उपकरण होने चाहिए।
• हर दवा की एक्सपायरी डेट चेक करके समय पर बदली जाए।
• किट पूरी तरह साफ-सुथरी होनी चाहिए (Housekeeping अच्छी हो)।
• किसी भी वस्तु की कमी नहीं होनी चाहिए।
 
⭐ 3. फर्स्ट-एड किट में क्या-क्या होना चाहिए?
नीचे दी गई सभी वस्तुएँ किट में अनिवार्य रूप से होनी चाहिए:
✔ 1. प्लास्टर (Band-aid)
विभिन्न आकार और प्रकार के प्लास्टर — छोटी, बड़ी, गोल, चौकोर।
✔ 2. Sterile Gauze Dressings
छोटे, मध्यम और बड़े बाँझ पट्टियाँ — घाव पर बाँधने के लिए।
✔ 3. Eye Dressings
कम से कम 2 बाँझ नेत्र पट्टियाँ।
✔ 4. Triangular Bandage
त्रिकोणीय पट्टी — हाथ, कंधे या हड्डी टूटने पर सहारा देने के लिए।
✔ 5. Crepe Bandages
लचीली पट्टी — मोच या सूजन होने पर उपयोग होती है।
✔ 6. Burn Dressing
जलने पर लगाने वाली ड्रेसिंग।
✔ 7. Dettol / Antiseptic Liquid
घाव साफ करने के लिए।
✔ 8. Safety Pins
पट्टियाँ बांधने के लिए।
✔ 9. Disposable Gloves (Sterile)
संक्रमण से बचने के लिए।
✔ 10. Tweezer (चिमटी)
काँटा, शीशा या छोटे कण निकालने के लिए।
✔ 11. Scissors (कैंची)
पट्टी या कपड़े काटने के लिए।
✔ 12. Sticky Tape (चिपकने वाला टेप)
ड्रेसिंग चिपकाने के लिए।
✔ 13. Thermometer (Digital)
बुखार मापने के लिए।
✔ 14. Skin Rash Cream
Hydrocortisone, Calendula या अन्य रैश क्रीम।
✔ 15. Insect Bite Cream/Spray
मच्छर या कीड़े के काटने पर राहत देने वाला।
✔ 16. Antiseptic Cream
घाव को संक्रमण से बचाने के लिए।
✔ 17. Distilled Water (आसुत जल)
घाव या आँख साफ करने के लिए।
✔ 18. Eye Wash / Eye Bath
आँख में धूल, रसायन या जलन होने पर धोने के लिए।
 
⭐ 4. किट को कैसे मेंटेन करें?
✔ दवाओं की एक्सपायरी नियमित चेक करें
एक रजिस्टर बनाकर तारीखें लिखें।
✔ समय पर बदलें
खराब, पुरानी या खत्म दवाओं को तुरंत बदलें।
✔ साफ-सफाई रखें
किट हमेशा साफ-सुथरी और व्यवस्थित होनी चाहिए।
✔ ड्राइवरों को प्रशिक्षण दें
हर ड्राइवर को किट को कैसे उपयोग करना है, इसकी ट्रेनिंग देना जरूरी है।
✔ सुपरवाइजर नियमित चेक करें
मासिक या साप्ताहिक निरीक्षण अनिवार्य है।
 
⭐ 5. ड्राइवर और ट्रांसपोर्टर की जिम्मेदारी
• ड्राइवर को किट के हर सामान का उपयोग करना आना चाहिए।
• ट्रांसपोर्टर यह सुनिश्चित करें कि किट हमेशा पूरी हो।
• सुपरवाइजर समय-समय पर किट का ऑडिट करें।
• दवाओं की तारीख देखने के लिए एक रजिस्टर बनाएँ।
 
⭐ निष्कर्ष
फर्स्ट-एड किट छोटी लग सकती है, लेकिन यह किसी की जान बचाने में भी सक्षम है।
इसलिए इसे हमेशा पूरी, साफ और अपडेटेड रखना बहुत जरूरी है।', NULL, 0, 8, 1)
