INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_13', 'Training 13 — Smith System (5 Rules)', 'Hindi transcript covering the 5 core rules of the Smith System for safe driving.', 'स्मिथ सिस्टम के 5 मुख्य नियम

यह दस्तावेज़ एयर लिक्विड कंपनी के लिए सड़क सुरक्षा प्रशिक्षण पर आधारित है, जिसमें स्मिथ सिस्टम के 5 मुख्य नियम बताए गए हैं। ये नियम ड्राइविंग को सुरक्षित बनाने के लिए वाहन के लिए जगह, ड्राइवर की दृश्यता और निर्णय लेने के समय पर जोर देते हैं।

मुख्य नियम 1: स्टीयरिंग में ऊंचा निशाना लगाएं (Aim High In Steering)
ड्राइविंग के दौरान आंखों को स्टीयरिंग से दूर ऊपर की ओर रखें, जैसे 12-15 सेकंड या 3-6 सेकंड आगे। इससे आप सड़क का बड़ा चित्र देख पाएंगे और खतरे पहले देख सकेंगे।

मुख्य नियम 2: पूरा दृश्य लें (Get The Big Picture)
सड़क का पूरा नजारा समझें, जिसमें बाएं-दाएं, आगे-पीछे सब कुछ शामिल हो। पेरिफेरल विजन (180 डिग्री) का उपयोग करें ताकि फोकस के बिना भी खतरे नजर आएं।

मुख्य नियम 3: आंखें हिलाते रहें (Keep Your Eyes Moving)
आंखों को हर 2-4 सेकंड में हिलाएं, एक जगह 2 सेकंड से ज्यादा न टिकाएं। इससे आप लगातार नई जानकारी इकट्ठा कर सकेंगे और आश्चर्यजनक स्थितियों से बचेंगे।

मुख्य नियम 4: खुद को बाहर निकालने का रास्ता छोड़ें (Leave Yourself An Out)
हमेशा वाहन के चारों ओर जगह रखें ताकि जरूरत पड़ने पर मूव कर सकें। अन्य वाहनों से दूरी बनाए रखें।

मुख्य नियम 5: सुनिश्चित करें कि वे आपको देखें (Make Sure They See You)
अन्य ड्राइवरों को अपनी मौजूदगी दिखाएं, जैसे हॉर्न, लाइट या सिग्नल से। उनकी आंखों पर नजर रखें ताकि पता चले कि वे आपको नोटिस कर रहे हैं या नहीं।', NULL, 0, 13, 1)
