INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_14', 'Training 14 — Accident & Incident Reporting', 'Hindi transcript on the importance of timely accident/incident reporting and immediate actions.', 'दुर्घटना और घटना की रिपोर्टिंग

यह दस्तावेज़ एयर लिक्विड कंपनी के सड़क सुरक्षा प्रशिक्षण का हिस्सा है, जो दुर्घटना और घटना रिपोर्टिंग पर केंद्रित है। इसमें रिपोर्टिंग के महत्व और तत्काल कार्रवाई पर जोर दिया गया है।
रिपोर्टिंग का महत्व
हर दुर्घटना और घटना की सूचना देना बहुत जरूरी है ताकि समय पर मदद और उचित कार्रवाई की जा सके। समय पर रिपोर्टिंग से तत्काल सहायता मिलती है, सुधारात्मक कदम उठाए जा सकते हैं, और गंभीर मामलों में जान बचाई जा सकती है। यह सरकारी अधिकारियों से मदद लेने, स्पष्ट तस्वीर पेश करने, तथा भविष्य के लिए निवारक योजनाएं बनाने में सहायक होती है।
मुख्य लाभ
• तत्काल सहायता प्रदान करना।
• सुधारात्मक कार्रवाई की संभावना बढ़ाना।
• जान जोखिम में होने पर समय पर सूचना से बचाव।
• सरकारी सहायता प्राप्ति में आसानी।
• सही निर्णय के लिए पूरी जानकारी उपलब्ध कराना।
• डेटाबेस से सुरक्षा नीतियां और निवारक कार्ययोजना तैयार करना।
कार्रवाई निर्देश
प्रत्येक दुर्घटना या घटना के बारे में यथाशीघ्र साइट वितरण अधिकारी (एएल) और परिवहन पर्यवेक्षक को सूचित करें। यह प्रक्रिया सुरक्षा को प्राथमिकता देती है।', NULL, 0, 14, 1)
