INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_15', 'Training 15 — PPE Use (Personal Protective Equipment)', 'Hindi transcript on PPE requirements and correct usage.', 'पीपीई का उपयोग (व्यक्तिगत सुरक्षात्मक उपकरण)
एयर लिक्विड द्वारा पीपीई स्वास्थ्य और सुरक्षा विधान के अंतर्गत प्रदान किया जाता है, जो कर्मचारियों को मुफ्त में दिया जाता है। खराब या खोए हुए पीपीई की रिपोर्ट करना कर्मचारी का दायित्व है। कार्य शुरू करने से पहले पर्यवेक्षक से सही पीपीई प्राप्त करें—बिना सही पीपीई के कोई कार्य न शुरू।

आंखों की सुरक्षा
दाबग्रस्त सिस्टम पर काम करते समय आंखों की सुरक्षा अनिवार्य है। सेफ्टी ग्लासेस, गॉगल्स या लिक्विड के लिए फेस शील्ड पहनें। चश्मा पहनने वालों के लिए प्रिस्क्रिप्शन आई प्रोटेक्शन उपलब्ध है—पर्यवेक्षक से संपर्क करें।

श्रवण सुरक्षा
कान संरक्षण क्षेत्रों में इयर डिफेंडर्स और इयर प्लग्स पहनें। गैस वेंटिंग के दौरान दोनों (प्लग्स और डिफेंडर्स) का उपयोग करें। धातु सिलेंडरों के टकराव से उत्पन्न शोर से सुनने की क्षमता की रक्षा करें।

हाथ और पैरों की सुरक्षा
सिलेंडर हैंडलिंग के लिए जनरल प्रोटेक्शन ग्लव्स रिस्ट बैंड्स के साथ पहनें; नियमित रूप से बदलें और खराब मौसम में अतिरिक्त जोड़ी लें। सेफ्टी फुटवियर में मेटाटार्सल प्रोटेक्शन हो जो पैरों को कुचलने से बचाए। ड्राई आइस हैंडलिंग के लिए थर्मल ग्लव्स उपयोग करें।

सुरक्षात्मक वस्त्र और अन्य नियम
साइट पर हाई विजिबिलिटी क्लोथिंग पहनें ताकि वाहन चालक आपको देख सकें; ओवरॉल्स साप्ताहिक बदलें और लॉन्ड्री सर्विस का उपयोग करें। सुरक्षा चेतावनी संकेतों का पालन करें जैसे हेलमेट क्षेत्र में हेलमेट पहनना। कार्य के लिए मानक संचालन प्रक्रिया (एसओपी) में निर्दिष्ट सही पीपीई पहनें; क्षतिग्रस्त पीपीई के लिए पर्यवेक्षक से रिप्लेसमेंट लें। पीपीई खतरे से अंतिम रक्षा रेखा है—हमेशा पहनें!', NULL, 0, 15, 1)
ON DUPLICATE KEY UPDATE
