  is_active = VALUES(is_active);

INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_16', 'Training 16 — Tyre Inspection Checklist', 'Hindi checklist for tyre inspection steps and sign-off.', 'टायर चेकलिस्ट (टायर निरीक्षण सूची)
टायर निरीक्षण चेकलिस्ट वाहन संख्या, ड्राइवर नाम, स्थान और तिथि के साथ शुरू होती है। यह चेकपॉइंट्स की सूची प्रदान करती है जो टायरों की सुरक्षा सुनिश्चित करती है। निरीक्षण के दौरान स्वीकार्य (✓), सावधानी (C), या अस्वीकार्य (✗) चिह्न लगाएं।
 
चेकपॉइंट्स की सूची
• 1. नेल्स या स्टोन्स के लिए दृश्य जांच करें।
• 2. वाल्व कैप्स, एक्सटेंशन वाल्व्स में संभावित लीकेज के लिए दृश्य जांच करें।
• 3. टायर में एयर प्रेशर जांचें—अनुशंसित रेंज 120 से 130 PSI।
• 4. टायर साइडवॉल्स पर बम्प्स और कट्स के लिए दृश्य जांच करें।
• 5. अनियमित पहनाव यदि हो तो वाहन सस्पेंशन और रिम्स पर नट्स जांचें।
• 6. टायर की गहराई पूरे चौड़ाई और परिधि पर 1.6 मिमी (75%?) जांचें।
• 7. एक ही एक्सेल पर समान निर्माता, प्रकार, आकार, सर्विस विवरण और पहनाव वाले टायर ही उपयोग करें।
• 8. डायरेक्शनल टायरों का विपरीत दिशा में उपयोग न करें।

कार्य और हस्ताक्षर
प्रत्येक कार्य (टास्क) के लिए R1, R2, L1, L2, S1 आदि कॉलम में स्थिति मार्क करें। टिप्पणियां (रिमार्क्स) दर्ज करें। पर्यवेक्षक और ड्राइवर हस्ताक्षर अनिवार्य हैं। प्रशिक्षण उपस्थिति फॉर्म में विषय, तिथि, स्थान, समय, फैकल्टी और अवधि भरें।', NULL, 0, 16, 1)
ON DUPLICATE KEY UPDATE
