INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_21', 'Training 21 — Driver ID Card (DIC) Guidelines', 'Hindi transcript on proper use and handling of Driver Identification Cards.', 'डीआईसी (ड्राइवर पहचान कार्ड) दिशा-निर्देश
डीआईसी (Driver Identification Card) एक कार्ड होता है, जिससे कंपनी यह पहचानती है कि गाड़ी कौन-सा ड्राइवर चला रहा है।

यह ड्राइवर की सुरक्षा, काम का रिकॉर्ड, और अच्छे प्रदर्शन पर इनाम देने में मदद करता है।
इसलिए इसका सही उपयोग बहुत जरूरी है।
 
1. ड्राइवर की जिम्मेदारियाँ
1. अपने खुद के डीआईसी का ही उपयोग करें
• हमेशा केवल अपना डीआईसी इस्तेमाल करना है।
• किसी दूसरे ड्राइवर का डीआईसी इस्तेमाल करना सख़्त मना है।
• ऐसा करने पर कड़ी कार्रवाई हो सकती है।
2. अपने डीआईसी का ध्यान रखें
• डीआईसी खो जाए, टूट जाए या खराब हो जाए, तो तुरंत:
  o अपने सुपरवाइजर को बताएं
  o डिस्ट्रीब्यूशन ऑफिसर से संपर्क करें
3. इन परिस्थितियों में डीआईसी वापस करें
• अगर कोई अज्ञात / किसी का छोड़ा हुआ डीआईसी मिले
• जब आप छुट्टी पर जा रहे हों
• डीआईसी बदलवाना हो
4. छुट्टी से लौटने पर
• ड्राइविंग शुरू करने से पहले पहले अपनी साइट पर रिपोर्ट करें
• उसके बाद ही किसी यात्रा/डिलीवरी पर जाएं
 
2. ड्राइवर सुपरवाइजर की जिम्मेदारियाँ
1. यह सुनिश्चित करें कि सभी ड्राइवर सिर्फ अपना डीआईसी उपयोग करें
2. ड्राइवर बदलने या नौकरी छोड़ने पर
• उस ड्राइवर का डीआईसी वापस लेकर डिस्ट्रीब्यूशन ऑफिसर को दें
3. अज्ञात डीआईसी मिलने पर
• उसे तुरंत डिस्ट्रीब्यूशन ऑफिसर को जमा करें
 
3. डिस्ट्रीब्यूशन ऑफिसर की जिम्मेदारियाँ
1. नए ड्राइवर के लिए डीआईसी जारी करना
• नए योग्य ड्राइवर का डीआईसी जारी करने के लिए रोड सेफ्टी टीम से संपर्क करें
2. रिकॉर्ड रखना
• कौन-सा डीआईसी किस ड्राइवर को दिया गया
• कौन-सा डीआईसी वापस आया
इन सभी का सही रिकॉर्ड रखना
3. डीआईसी खराब या खो जाने पर सूचना देना
• ऐसे मामलों की सूचना तुरंत रोड सेफ्टी टीम को दें
4. डीआईसी का स्टॉक बनाए रखना
• डीआईसी कम होने पर, खत्म होने से एक महीने पहले रोड सेफ्टी टीम को बताएं
5. एक ड्राइवर = एक डीआईसी
• हर ड्राइवर के पास केवल एक ही डीआईसी होना चाहिए
• अगर किसी के पास अतिरिक्त डीआईसी हो, तो उसे वापस लेना है
 
महत्वपूर्ण नोट
• जब किसी ट्रक में नया कार्ड स्वाइप सिस्टम लग जाए,
तो पुराने डीवीआर में लगने वाले डीआईसी तुरंत वापस डिस्ट्रीब्यूशन ऑफिसर को जमा करें।
 
एक ड्राइवर – एक डीआईसी – ड्राइविंग सिर्फ अपने डीआईसी से', NULL, 0, 21, 1)
ON DUPLICATE KEY UPDATE
