INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_22', 'Training 22 — Time Management on Road', 'Hindi transcript on driving time limits, breaks, and speed rules.', 'सड़क पर समय प्रबंधन
1. लगातार ड्राइविंग की समय सीमा – 3 घंटे 30 मिनट
एक बार में अधिकतम 3 घंटे 30 मिनट ही लगातार ड्राइव चलाया जा सकता है।
इससे ज्यादा लगातार ड्राइव करना थकान और दुर्घटना का कारण बन सकता है।
 
2. लगातार ड्राइव के बाद आराम – 30 मिनट
3 घंटे 30 मिनट की ड्राइव के बाद कम से कम 30 मिनट का आराम लेना जरूरी है।
इस ब्रेक से चालक की थकान कम होती है और सड़क पर ध्यान बेहतर रहता है।
 
3. एक दिन में ड्राइविंग की सीमा – 8 घंटे
चालक एक दिन में अधिकतम 8 घंटे तक ही ड्राइव कर सकता है।
यह सुरक्षा और स्वास्थ्य को ध्यान में रखकर बनाया गया नियम है।
 
4. एक सप्ताह की ड्राइविंग सीमा – 56 घंटे
सप्ताह में कुल मिलाकर 56 घंटे से ज्यादा ड्राइव नहीं कर सकते।
 
5. दो सप्ताह की ड्राइविंग सीमा – 100 घंटे
दो हफ्तों में ड्राइविंग का कुल समय 100 घंटे से अधिक नहीं होना चाहिए।
यह ओवरटाइम और अत्यधिक थकान को रोकने के लिए है।
 
6. अधिकतम दैनिक ड्राइविंग सीमा – 11 घंटे (सभी ब्रेक मिलाकर)
कभी-कभी आवश्यकता होने पर (जैसे लंबी यात्रा में), एक दिन में ड्राइविंग का कुल समय 11 घंटे तक हो सकता है, लेकिन यह एक विशेष सीमा है। सामान्य सीमा 8 घंटे ही है।
 
7. रात में ड्राइविंग निषेध – 11:30 PM से 4:30 AM तक
इस समय ड्राइविंग पूर्ण रूप से प्रतिबंधित है।
रात में ड्राइविंग जोखिम भरी होती है—नींद, कम दृश्यता, दुर्घटना की संभावना अधिक रहती है।
 
8. दिन में न्यूनतम आराम – 9 घंटे
एक दिन में चालक को कम से कम 9 घंटे का आराम मिलना चाहिए।
इससे अगले दिन सुरक्षित ड्राइविंग सुनिश्चित होती है।
 
9. वाहन की अधिकतम गति सीमा – 50 KMPH
वाहन किसी भी परिस्थिति में 50 किमी/घंटा से अधिक की गति पर नहीं चलना चाहिए।
यह सुरक्षा और नियमों के पालन के लिए अनिवार्य है।', NULL, 0, 22, 1)
