INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_23', 'Training 23 — Safe Truck Parking Rules', 'Hindi transcript on safe parking practices for trucks in hotels/dhabas and roadside halts.', '📌 सुरक्षित ट्रक पार्किंग नियम — पूरा निकाला हुआ टेक्स्ट
सुरक्षित ट्रक पार्किंग नियम

वाहन को पार्किंग ड्राइविंग का एक अनिवार्य हिस्सा है। पार्किंग स्थानों का गलत/खराब चयन आपको परेशानियों में डाल सकता है। जब भी हम आपके वाहन को पार्क कर रहे हों, तो निम्नलिखित बातों पर ध्यान देना चाहिए।

होटल या ढाबा / रेस्ट में पार्किंग
• हमेशा पूर्व निर्धारित ढाबा या होटल में वाहन पार्क करें।
• वाहन को हमेशा हाईवे किनारे बिजली लाइनें और पेड़ों से दूर पार्क करें।
• वाहन को हमेशा वहीं पार्क करें जहाँ आगे पास वाहन को घूमने के लिए पर्याप्त जगह हो।
• वाहन को हमेशा इस तरह पार्क करें कि अन्य वाहनों में आवाजाही या घूमने के लिए पर्याप्त जगह हो।
• वाहन पार्क करने से पहले हमेशा पार्किंग मार्ग के बारे में सोचो।
• कभी भी होटल और गोलों में/या पार्किंग क्षेत्र में वाहन पार्क न करें।
• बरसात के मौसम में कभी भी निचले इलाकों में वाहन पार्क न करें।
• रोड टर्न पर कभी भी वाहन पार्क न करें।
• वाहन को हमेशा खुली आग या सोर्स से दूर पार्क करें।
• रात्री पार्क में वाहन इस प्रकार रखें कि मध्य रात्री या विशेष के समय वाहनों को न चलना पड़े।
• अंधे क्षेत्र में वाहन पार्क करने से बचें।
• कभी भी ढलान पर वाहन पार्क न करें।
• चेक करें कि ढाबा या होटल प्वाइंट पर मूलभूत सुविधाएं उपलब्ध हैं। जैसे वॉशरूम… चालक/मज़दूर की सुरक्षा के दृष्टिकोण से उचित सुविधाएं हो।
• छोटे वाहन चालकों को कोशिश करनी चाहिए कि वे होटल के कमरों में रुकें।
• वाहन को रोकने के लिए हमेशा हैंड ब्रेक लगाएं।
• रुक हुए वाहन न्यूट्रल गियर में होने चाहिए।

सड़क किनारे पार्किंग या हॉल्ट
• हमेशा ट्रक को या सुरक्षित स्थान पर वाहन पार्क करने का प्रयास करें।
• पार्किंग लाइट हर समय चालू रहना चाहिए।
• खराब इलाकों में हॉर्न में ट्रैफिक कोन का प्रयोग करें।
• हमेशा ट्रक की हेजर्ड लाइट/पार्किंग लाइट का प्रयोग करें।
• खड़े वाहन की आगे या पीछे खड़े न हों।
• ट्रक के पीछे से 15 मीटर दूर ट्रैफिक कोन को ठीक करें।
• यदि सड़क फिसल में, तो वाहन के आगे और एक शंकु लगाना जाना चाहिए।
• सड़क के आसपास शोरहर पर वाहन को कभी भी न रोकें।
• सड़क के आसपास सड़क के किनारों के बिल्कुल बारी पार्क करें।
• वाहन के बाईं ओर के चक्कर मै निपुण होने के लिए स्वयं चालक या सहायक को सहायता लें।
• वाहन से उतरते समय चालक को सावधान रहने की जरूरत है।
• वाहन पर ब्रेक लगाएं।
• वाहन को कभी भी लावारिस न छोड़ें।
• वाहन को कभी भी मोड़ या अंधे स्थान पर न रोकें।', NULL, 0, 23, 1)
