INSERT INTO safety_training_modules (code, title, description, transcript, audio_url, duration_seconds, sort_order, is_active)
VALUES
('training_27', 'Training 27 — On-the-Job Training (OJT) for Drivers', 'Hindi transcript on OJT approach, scope, and benefits for drivers.', '🚚 ड्राइवरों के लिए ऑन-द-जॉब ट्रेनिंग (OJT) 
OJT मतलब—काम करते-करते सीखना।
यह ऐसा प्रशिक्षण है जिसमें ड्राइवर कागज़ या क्लास में पढ़कर नहीं, बल्कि असली सड़क और असली काम करते हुए सीखते हैं।
इस दौरान एक अनुभवी ड्राइवर या सुपरवाइज़र नई ड्राइवर को हर काम सिखाता है।
 
🔹 OJT क्यों जरूरी है?
• ड्राइवर को असली स्थिति का अनुभव मिलता है
• सड़क, वाहन और कंपनी के नियमों को सही तरीके से समझ पाता है
• गलतियाँ कम होती हैं
• ड्राइवर जल्दी आत्मविश्वासी और कुशल बनता है
 
🔹 ड्राइवरों के लिए OJT के मुख्य भाग 
✔ 1. सुरक्षित और रक्षात्मक ड्राइविंग
• सड़क पर सुरक्षित तरीके से वाहन चलाना
• स्पीड लिमिट का पालन
• कठिन सड़क स्थितियों में सही निर्णय लेना
• लंबे समय तक ड्राइविंग करते हुए भी सतर्क रहना
 
✔ 2. कंपनी के नियम और प्रक्रियाएँ
ड्राइवर सीखते हैं:
• कंपनी की सुरक्षा नीतियाँ
• दुर्घटना या घटना होने पर रिपोर्ट कैसे करें
• शराब/नशीले पदार्थों से दूर रहने के नियम
 
✔ 3. वाहन संचालन और चेकिंग
OJT में ड्राइवर को सिखाया जाता है:
• यात्रा से पहले वाहन चेक (Pre-trip inspection)
• यात्रा के बाद वाहन चेक
• ब्रेक, टायर, लाइट, फ्यूल आदि का अभ्यास
• एयर ब्रेक या अलग-अलग प्रकार के ट्रेलर की जानकारी
 
✔ 4. नेविगेशन और रास्ता योजना (Route planning)
ड्राइवर सीखते हैं:
• GPS चलाना
• मल्टी-स्टॉप डिलीवरी की योजना बनाना
• ट्रैफिक और रोड बंद होने पर वैकल्पिक रास्ता चुनना
• समय प्रबंधन
 
✔ 5. लोडिंग और अनलोडिंग (Cargo Handling)
• सामान को सही तरीके से चढ़ाना और उतारना
• कार्गो को सुरक्षित बांधना
• नुकसान और दुर्घटना से बचना
 
✔ 6. कागजी काम और तकनीक (Documentation & Technology)
ड्राइवर सीखते हैं:
• आवश्यक दस्तावेज भरना
• ELD (Electronic Logging Device) या इन-कॅब तकनीक का उपयोग
• डिलीवरी का रिकॉर्ड रखना
 
✔ 7. ग्राहक सेवा (Customer Handling)
डिलीवरी वाले ड्राइवरों के लिए:
• ग्राहक से अच्छा व्यवहार
• समस्या आने पर शांत रहकर समाधान करना
 
🟢 OJT के फायदे (Benefits of OJT for Drivers)
✔ 1. आत्मविश्वास बढ़ता है
ड्राइवर असली स्थिति में खुद काम करता है, जिससे डर कम होता है और आत्मविश्वास बढ़ता है।
✔ 2. सीखने की गति तेज होती है
काम करते-करते सीखने से ड्राइवर जल्दी कुशल बन जाता है।
✔ 3. कंपनी में लंबे समय तक काम करने की संभावना बढ़ती है
जब ड्राइवर को प्रशिक्षण मिलता है, वह कंपनी से जुड़ाव महसूस करता है और नौकरी छोड़ने की संभावना कम होती है।
✔ 4. कौशल में सुधार होता है
• ड्राइविंग कौशल
• समस्या हल करने की क्षमता
• संचार कौशल
• नई तकनीक अपनाने की क्षमता
सभी में सुधार होता है।', NULL, 0, 27, 1)
